CREATE TABLE users (id CHAR(36) PRIMARY KEY, display_name VARCHAR(100) NOT NULL, created_at DATETIME(6) NOT NULL);
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id CHAR(36) NOT NULL, expires_at DATETIME(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE categories (id VARCHAR(50) PRIMARY KEY,title VARCHAR(100) NOT NULL,sort_order INT NOT NULL);
CREATE TABLE templates (id VARCHAR(100) PRIMARY KEY,category_id VARCHAR(50) NOT NULL,title VARCHAR(100) NOT NULL,description TEXT NOT NULL,cover_key VARCHAR(100) NOT NULL,result_key VARCHAR(100) NOT NULL,required_image_count INT NOT NULL,max_file_size_bytes BIGINT NOT NULL,sort_order INT NOT NULL,FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE assets (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,storage_key VARCHAR(100) NOT NULL UNIQUE,original_name VARCHAR(255) NOT NULL,mime_type VARCHAR(30) NOT NULL,size_bytes BIGINT NOT NULL,width INT NOT NULL,height INT NOT NULL,created_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE tasks (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,template_id VARCHAR(100) NOT NULL,template_title VARCHAR(100) NOT NULL,status VARCHAR(20) NOT NULL,stage VARCHAR(20),failed_stage VARCHAR(20),failure_code VARCHAR(50),failure_reason VARCHAR(300),result_key VARCHAR(100),version BIGINT NOT NULL DEFAULT 1,simulation_json JSON NOT NULL,created_at DATETIME(6) NOT NULL,started_at DATETIME(6),completed_at DATETIME(6),updated_at DATETIME(6) NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(template_id) REFERENCES templates(id),INDEX ix_user_history(user_id,created_at,id),INDEX ix_status(status),CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED')));
CREATE TABLE task_assets (task_id CHAR(36) NOT NULL,asset_id CHAR(36) NOT NULL,slot_index INT NOT NULL,PRIMARY KEY(task_id,slot_index),UNIQUE(task_id,asset_id),FOREIGN KEY(task_id) REFERENCES tasks(id),FOREIGN KEY(asset_id) REFERENCES assets(id));
CREATE TABLE task_steps (task_id CHAR(36) NOT NULL,stage VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,started_at DATETIME(6),completed_at DATETIME(6),failure_reason VARCHAR(300),PRIMARY KEY(task_id,stage),FOREIGN KEY(task_id) REFERENCES tasks(id));
